    ctwner.atter = 100.0 * sqrt(ancatt) / ancatt
  ctowns.att = ancatt / (outpt.st * vel.wz) * 1000000000000.0
  ctwner.alper = 0.0
  if not (ancion == 0.0):
    ctwner.alper = 100.0 * sqrt(ancion) / ancion
  ctowns.alpha = ancion / (outpt.st * vel.wz) * 1000000000000.0
  return
